// ═══ BASIC USAGE: limit concurrent DB connections ═══
Semaphore dbPool = new Semaphore(5);  // max 5 concurrent DB connections!

void queryDB(String sql) throws InterruptedException {
    dbPool.acquire();  // take a permit (blocks if 5 already taken!)
    try {
        executeQuery(sql);
    } finally {
        dbPool.release();  // return permit (ALWAYS in finally!)
    }
}
// 200 threads calling queryDB → max 5 execute simultaneously!
// Others wait in FIFO (if fair) or randomly (if non-fair).

// ═══ tryAcquire — non-blocking ═══
if (dbPool.tryAcquire()) {          // returns immediately!
    try { executeQuery(sql); }
    finally { dbPool.release(); }
} else {
    return "Service busy, try later";  // no permit available!
}

// ═══ tryAcquire with timeout ═══
if (dbPool.tryAcquire(5, TimeUnit.SECONDS)) {
    try { executeQuery(sql); }
    finally { dbPool.release(); }
} else {
    throw new TimeoutException("DB pool full for 5 seconds!");
}

// ═══ BINARY SEMAPHORE vs synchronized ═══
Semaphore binarySem = new Semaphore(1);  // 1 permit = binary!

// Binary semaphore:
binarySem.acquire();
try { criticalSection(); }
finally { binarySem.release(); }
// ANY thread can release! NOT reentrant! NOT thread-owned!

// synchronized:
synchronized (lock) { criticalSection(); }
// ONLY owning thread releases! REENTRANT! Thread-owned!

// Key difference: Thread-A acquires semaphore. Thread-B can release it!
// synchronized: Thread-A locks. ONLY Thread-A can unlock!

// ═══ FAIR SEMAPHORE ═══
Semaphore fairSem = new Semaphore(5, true);  // fair = FIFO!
// Longest-waiting thread gets the next permit!
// Non-fair (default): barging allowed — faster but possible starvation.
