// ─── File: src/test/java/com/bank/semaphore/SemaphoreTest.java ───
package com.bank.semaphore;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class SemaphoreTest {

    // ═══ Limits concurrent access ═══
    @Test
    void semaphore_limitsConcurrency() throws InterruptedException {
        Semaphore sem = new Semaphore(3);  // max 3!
        AtomicInteger maxConcurrent = new AtomicInteger(0);
        AtomicInteger current = new AtomicInteger(0);
        int threads = 20;
        CountDownLatch done = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                try {
                    sem.acquire();
                    int c = current.incrementAndGet();
                    maxConcurrent.updateAndGet(m -> Math.max(m, c));
                    Thread.sleep(50);
                    current.decrementAndGet();
                } catch (InterruptedException e) { }
                finally { sem.release(); done.countDown(); }
            }).start();
        }
        done.await();
        assertThat(maxConcurrent.get()).isLessThanOrEqualTo(3);  // never > 3!
    }

    // ═══ tryAcquire — non-blocking ═══
    @Test
    void tryAcquire_nonBlocking() {
        Semaphore sem = new Semaphore(1);
        assertThat(sem.tryAcquire()).isTrue();   // got it!
        assertThat(sem.tryAcquire()).isFalse();  // no permit! Returns immediately!
        sem.release();
        assertThat(sem.tryAcquire()).isTrue();   // available again!
        sem.release();
    }

    // ═══ Different thread can release ═══
    @Test
    void differentThread_canRelease() throws InterruptedException {
        Semaphore sem = new Semaphore(0);  // starts with 0 permits!
        boolean[] acquired = {false};

        Thread waiter = new Thread(() -> {
            try { sem.acquire(); acquired[0] = true; }
            catch (InterruptedException e) { }
        });
        waiter.start();
        Thread.sleep(100);
        assertThat(acquired[0]).isFalse();  // blocked! No permits!

        // DIFFERENT thread releases!
        sem.release();  // main thread releases → waiter unblocked!
        waiter.join(2000);
        assertThat(acquired[0]).isTrue();  // got it!
    }

    // ═══ Fair semaphore: FIFO ═══
    @Test
    void fairSemaphore_fifo() throws InterruptedException {
        Semaphore fair = new Semaphore(1, true);
        assertThat(fair.isFair()).isTrue();
        fair.acquire();
        fair.release();
    }

    // ═══ availablePermits for monitoring ═══
    @Test
    void monitoring_availablePermits() {
        Semaphore sem = new Semaphore(10);
        sem.tryAcquire();
        sem.tryAcquire();
        assertThat(sem.availablePermits()).isEqualTo(8);  // 2 taken!
    }
}
